head.script:
scwin.onpageload = function () {
    // DataList에 초기 데이터 할당
    scwin.initData();
};

/**
 * DataList 'dlt_exam_1'에 데이터 할당하기
 */
scwin.initData = function () {
    let data = [
        { "category": "Networking", "product": "SpeedLink" },
        { "category": "Servers", "product": "EcoServe" },
        { "category": "Networking", "product": "LinkSecure" },
        { "category": "Servers", "product": "ServeTech" }
    ];

    // DataList 'dlt_exam_1', 'dlt_exam_2'에 데이터 할당하기
    dlt_exam_1.setJSON(data);
    dlt_exam_2.setJSON(data);

    // 테스트를 위해 DataList 'dlt_exam_1', 'dlt_exam_2'에 필터 적용하기 - 'Category' 컬럼의 값이 'Servers'인 데이터 출력
    dlt_exam_1.setColumnFilter({
        type: "row",
        colIndex: "category",
        key: "Servers",
        condition: "and",
        exactMatch: true
    });

    dlt_exam_2.setColumnFilter({
        type: "row",
        colIndex: "category",
        key: "Servers",
        condition: "and",
        exactMatch: true
    });
};

/**
 * 버튼 [1.1 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 JSON 형식으로 받기] 클릭 시
 */
scwin.btn_exam1_1_onclick = function (e) {
    // DataList 'dlt_exam_1'의 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam_1.getMatchedJSON("category", "Networking");

    // 로그 출력
    let strLog = "# DatList의 'getMatchedFromAllData' 속성의 설정 값: \"false\"";
    let strLog2 = "메소드 getMatchedJSON 호출 값 : \n";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(strLog2 + JSON.stringify(result), txa_log_1, false);
    console.log(strLog);
    console.log(strLog2);
    console.log(result);
};

/**
 * 버튼 [1.2 'Category' 컬럼의 값이 'Servers'과 일치하는 Row Index 받기] 클릭 시
 */
scwin.btn_exam1_2_onclick = function (e) {
    // DataList 'dlt_exam_1'의 'Category' 컬럼의 값이 'Servers'과 일치하는 Row Index를 반환받습니다.
    let result = dlt_exam_1.getMatchedIndex("category", "Servers");

    // 로그 출력
    let strLog = "# DatList의 'getMatchedFromAllData' 속성의 설정 값: \"false\"";
    let strLog2 = "메소드 getMatchedIndex 호출 값 : \n";
    $c.frame.printExampleLog(strLog, txa_log_1, false);
    $c.frame.printExampleLog(strLog2 + JSON.stringify(result), txa_log_1, false);
    console.log(strLog);
    console.log(strLog2);
    console.log(result);
};


/**
 * 버튼 [2.1 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 JSON 형식으로 받기] 클릭 시
 */
scwin.btn_exam2_1_onclick = function (e) {
    // DataList 'dlt_exam_2'의 'Category' 컬럼의 값이 'Networking'과 일치하는 데이터를 JSON으로 반환받습니다.
    let result = dlt_exam_2.getMatchedJSON("category", "Networking");

    // 로그 출력
    let strLog = "# DatList의 'getMatchedFromAllData' 속성의 설정 값: \"true\"";
    let strLog2 = "메소드 getMatchedJSON 호출 값 : \n";
    $c.frame.printExampleLog(strLog, txa_log_2, false);
    $c.frame.printExampleLog(strLog2 + JSON.stringify(result), txa_log_2, false);
    console.log(strLog);
    console.log(strLog2);
    console.log(result);
};

/**
 * 버튼 [2.2 'Category' 컬럼의 값이 'Servers'과 일치하는 Row Index 받기] 클릭 시
 */
scwin.btn_exam2_2_onclick = function (e) {
    // DataList 'dlt_exam_2'의 'Category' 컬럼의 값이 'Servers'과 일치하는 Row Index를 반환받습니다.
    let result = dlt_exam_2.getMatchedIndex("category", "Servers");

    // 로그 출력
    let strLog = "# DatList의 'getMatchedFromAllData' 속성의 설정 값: \"true\"";
    let strLog2 = "메소드 getMatchedIndex 호출 값 : \n";
    $c.frame.printExampleLog(strLog, txa_log_2, false);
    $c.frame.printExampleLog(strLog2 + JSON.stringify(result), txa_log_2, false);
    console.log(strLog);
    console.log(strLog2);
    console.log(result);
};

/**
 * textarea의 로그 삭제
 */
scwin.btn_clearLog_onclick = function (e) {
    let strTargetId = this.getUserData("userData1");
    let cmpTarget;
    if (strTargetId) {
        cmpTarget = $p.getComponentById(strTargetId) || txa_log;
    } else {
        cmpTarget = txa_log;
    }
    //textarea value를 빈문자열로 할당.
    cmpTarget.setValue("");
};
